def count_dominating_index_pairs(nums1, nums2):
    differences = sorted(first - second for first, second in zip(nums1, nums2))
    answer = 0
    left, right = 0, len(differences) - 1
    while left < right:
        if differences[left] + differences[right] > 0:
            answer += right - left
            right -= 1
        else:
            left += 1
    return answer

